00-spinta-ar-srautas:
/* 00-spinta-ar-srautas — palyginimas; žymos 1.2 / 5.5 / 10.1 s; 16 s (koncepcijos.js) */
.k-title { animation: k01T 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s both; }
@keyframes k01T { from { opacity: 0; transform: translateY(24px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes k01r0 { from { opacity: 0; transform: translateY(20px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01h0 { 0%, 10.25% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 12.19%, 32.50% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 34.38%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k01r1 { from { opacity: 0; transform: translateY(20px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01h1 { 0%, 37.13% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 39.06%, 61.25% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 63.13%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k01r2 { from { opacity: 0; transform: translateY(20px) scale(.985); } to { opacity: 1; transform: none; } }
.b-old { animation: k01r0 0.55s cubic-bezier(0.16, 1, 0.3, 1) 1.3s both, k01h0 16s linear 0s both; }
.b-arrow { animation: k01r1 0.55s cubic-bezier(0.16, 1, 0.3, 1) 5.6s both; }
.b-new { animation: k01r1 0.55s cubic-bezier(0.16, 1, 0.3, 1) 5.6s both, k01h1 16s linear 0s both; }
.b-summary { animation: k01r2 0.55s cubic-bezier(0.16, 1, 0.3, 1) 10.2s both; }
